script:
(function () {
  'use strict';
  // 403(b) projection: each year you defer contrib% of pay; the employer adds a match (match% of your
  // deferral up to matchCap% of pay) plus any flat nonelective contribution (% of pay). Deposits go in
  // monthly and compound monthly at the equivalent of the annual return minus the annual fee.
  // Optional caps: 402(g) deferral limit, age 50+ / 60-63 catch-up, the 403(b) 15-year rule, the 415(c)
  // limit on annual additions (age catch-ups excluded) and the 401(a)(17) pay limit on employer money.
  // 15-year rule (Pub. 571 ch. 4 and Worksheet 1, lines 5-16): with 15+ years of service for a qualifying
  // employer, the deferral limit rises by the least of $3,000; $15,000 minus the 15-year increases used
  // before; or $5,000 x years of service minus all elective deferrals to that employer in earlier years.
  // Deferrals above the basic limit count first as 15-year catch-up, then as age 50+ catch-up.
  // Checked in Node (fake DOM, whole script): $500/month at 7% for 30 years, no fee = $584,726 (annuity
  // formula with the monthly equivalent rate, same as 401k-calculator); a 1% fee gives the 6% value
  // ($487,256); caps $24,500 (age 40), $32,500 (55), $35,750 (61); 15-year rule with 20 years of service
  // and $90,000 earlier deferrals -> +$3,000 = $27,500 (Pub. 571's 2026 maximum); $98,000 earlier
  // deferrals -> +$2,000; $14,000 already used -> +$1,000 then nothing; age 55 + 15-year rule -> $35,500;
  // 30 years of service and no earlier deferrals -> +$3,000 for five years, then the $15,000 cap.
  // ---- 2026 IRS limits (IRS Notice 2025-67; Pub. 571, Rev. January 2026) -----------------------------
  var LIMITS = {
    year: 2026,
    deferral: 24500,        // 402(g) elective deferral limit (pre-tax + Roth)
    catchUp50: 8000,        // 414(v) catch-up, age 50 or older by year-end
    catchUp60to63: 11250,   // SECURE 2.0 higher catch-up, ages 60-63 (instead of the age-50 amount)
    annualAdditions: 72000, // 415(c) limit on all contributions except age catch-ups
    compensation: 360000,   // 401(a)(17) pay limit for employer contributions
    service: { yearly: 3000, lifetime: 15000, perYear: 5000, minYears: 15 } // 15-year rule (not indexed)
  };
  // ----------------------------------------------------------------------------------------------------

  function catchUpFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.catchUp50;
    return 0;
  }
  // Extra 15-year deferral room for a year: yos = years of service counting that year.
  function serviceCatchUp(yos, used, priorDeferrals) {
    if (yos < LIMITS.service.minYears) return 0;
    return Math.max(0, Math.min(LIMITS.service.yearly, LIMITS.service.lifetime - used,
                                LIMITS.service.perYear * yos - priorDeferrals));
  }

  // p: age, retireAge, salary, raise, balance, contrib, match, matchCap, nonelective, rate, fee, inflation
  //    (decimals), applyLimits, service (bool), yos, priorDeferrals, usedService.
  function project(p) {
    var years = p.retireAge - p.age;
    var mNet = Math.pow(1 + p.rate - p.fee, 1 / 12) - 1, mGross = Math.pow(1 + p.rate, 1 / 12) - 1;
    var bal = p.balance, noFee = p.balance, salary = p.salary, totYou = 0, totEr = 0, rows = [], capped = false;
    var used = p.usedService, prior = p.priorDeferrals, firstLimit = 0, firstService = 0;
    for (var y = 0; y < years; y++) {
      var ageNow = p.age + y;
      var you = salary * p.contrib, extra = 0, usedNow = 0;
      if (p.applyLimits) {
        extra = p.service ? serviceCatchUp(p.yos + y, used, prior) : 0;
        var maxYou = LIMITS.deferral + extra + catchUpFor(ageNow);
        if (y === 0) { firstLimit = maxYou; firstService = extra; }
        if (you > maxYou) { you = maxYou; capped = true; }
        usedNow = Math.min(Math.max(0, you - LIMITS.deferral), extra);
        used += usedNow;
        prior += you;
      }
      var pay = p.applyLimits ? Math.min(salary, LIMITS.compensation) : salary;
      var effPct = salary > 0 ? Math.min(you / salary, p.contrib) : 0;
      var er = pay * (p.match * Math.min(effPct, p.matchCap) + p.nonelective);
      if (p.applyLimits) {
        var regular = Math.min(you, LIMITS.deferral + extra);
        if (regular + er > LIMITS.annualAdditions) { er = Math.max(0, LIMITS.annualAdditions - regular); capped = true; }
      }
      var dep = (you + er) / 12;
      for (var m = 0; m < 12; m++) { bal = bal * (1 + mNet) + dep; noFee = noFee * (1 + mGross) + dep; }
      totYou += you; totEr += er;
      rows.push({ age: ageNow, salary: salary, you: you, er: er, extra: usedNow, balance: bal });
      salary = salary * (1 + p.raise);
    }
    return { balance: bal, real: bal / Math.pow(1 + p.inflation, years), you: totYou, er: totEr,
             growth: bal - p.balance - totYou - totEr, fees: noFee - bal, rows: rows, capped: capped,
             firstLimit: firstLimit, firstService: firstService };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var age = num('tbAge'), retireAge = num('tbRetireAge'), salary = num('tbSalary'), raise = num('tbRaise'),
        balance = num('tbBalance'), contrib = num('tbContrib'), match = num('tbMatch'), matchCap = num('tbMatchCap'),
        nonelective = num('tbNonelective'), rate = num('tbRate'), fee = num('tbFee'), inflation = num('tbInflation'),
        yos = num('tbYos'), prior = num('tbPrior'), used = num('tbUsed'),
        applyLimits = document.getElementById('tbLimits').checked, service = document.getElementById('tbService').checked;
    document.getElementById('tbServiceFields').hidden = !service;
    var error = document.getElementById('tbError');
    var bad = [age, retireAge, salary, raise, balance, contrib, match, matchCap, nonelective, rate, fee, inflation].some(isNaN) ||
              age !== Math.round(age) || retireAge !== Math.round(retireAge) ||
              age < 16 || age > 99 || retireAge <= age || retireAge > 100 || salary < 0 || balance < 0 ||
              raise < 0 || raise > 20 || contrib < 0 || contrib > 100 || match < 0 || match > 200 || matchCap < 0 ||
              matchCap > 100 || nonelective < 0 || nonelective > 100 || rate < 0 || rate > 30 || fee < 0 || fee > 5 ||
              inflation < 0 || inflation > 20 ||
              (service && ([yos, prior, used].some(isNaN) || yos < 0 || yos > 60 || prior < 0 || used < 0 || used > 15000));
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter whole-number ages from 16 to 99 with retirement above your age (up to 100), non-negative amounts, ' +
                          'percentages from 0 to 100 (match up to 200%), a return up to 30%, a fee up to 5% and inflation up to 20%' +
                          (service ? ', plus 0 to 60 years of service and up to $15,000 of 15-year catch-up already used.' : '.');
      return;
    }
    var r = project({ age: age, retireAge: retireAge, salary: salary, raise: raise / 100, balance: balance,
                      contrib: contrib / 100, match: match / 100, matchCap: matchCap / 100, nonelective: nonelective / 100,
                      rate: rate / 100, fee: fee / 100, inflation: inflation / 100, applyLimits: applyLimits,
                      service: service, yos: Math.floor(yos), priorDeferrals: prior, usedService: used });
    set('tbFuture', fmt(r.balance)); set('tbReal', fmt(r.real)); set('tbYou', fmt(r.you)); set('tbEr', fmt(r.er));
    set('tbGrowth', fmt(r.growth)); set('tbFees', fmt(r.fees));
    set('tbRetireLabel', 'Balance at age ' + retireAge);
    var first = r.rows[0];
    set('tbFirstYear', 'First year: you put in ' + fmt(first.you) + ' and your employer adds ' + fmt(first.er) +
        (applyLimits ? '. Your ' + LIMITS.year + ' deferral limit is ' + fmt(r.firstLimit) +
        (service ? ', including ' + fmt(r.firstService) + ' from the 15-year rule.' : '.') : '.'));
    var capEl = document.getElementById('tbCapped');
    capEl.hidden = !r.capped;
    if (r.capped) set('tbCapped', 'In some years your contribution or your employer\'s is reduced to stay within the ' +
        LIMITS.year + ' IRS limits shown below.');
    var body = document.getElementById('tbSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, fmt(row.salary), fmt(row.you), fmt(row.extra), fmt(row.er), fmt(row.balance)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    set('tbLimitDeferral', fmt(LIMITS.deferral)); set('tbLimitCatch50', fmt(LIMITS.catchUp50));
    set('tbLimitCatch60', fmt(LIMITS.catchUp60to63)); set('tbLimitService', 'Up to ' + fmt(LIMITS.service.yearly) + ' a year, ' +
        fmt(LIMITS.service.lifetime) + ' lifetime'); set('tbLimitTotal', fmt(LIMITS.annualAdditions));
    var form = document.getElementById('tbForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
